// Build monitor config from env and throttle checks using static state.
const staticData = this.getWorkflowStaticData('global');
const now = new Date();

const DEFAULT_POLL_INTERVAL_MINUTES = 2;
const pollMinutes = Math.max(
  1,
  parseInt($env.OGAME_POLL_INTERVAL_MINUTES || String(DEFAULT_POLL_INTERVAL_MINUTES), 10)
);
const pollMs = pollMinutes * 60 * 1000;
const lastPollMs = Number(staticData.lastPollMs || 0);

// Skip this execution if we are still inside the configured polling interval.
if (lastPollMs && (now.getTime() - lastPollMs) < pollMs) {
  return [];
}

const serverUrl = String($env.OGAME_SERVER_URL || '').trim().replace(/\/$/, '');
const statusEndpoint = String($env.OGAME_STATUS_ENDPOINT || '/api/status').trim();
const explicitStatusUrl = String($env.OGAME_STATUS_URL || '').trim();

const statusUrl = explicitStatusUrl || (serverUrl + (statusEndpoint.startsWith('/') ? '' : '/') + statusEndpoint);
if (!statusUrl) {
  throw new Error('Missing OGAME_STATUS_URL or OGAME_SERVER_URL + OGAME_STATUS_ENDPOINT');
}

staticData.lastPollMs = now.getTime();

return [{
  json: {
    statusUrl,
    authHeader: String($env.OGAME_STATUS_AUTH_HEADER || '').trim(),
    sendClearAlert: String($env.OGAME_SEND_CLEAR_ALERT || 'true').toLowerCase() === 'true',
    checkedAt: now.toISOString()
  }
}];

// Parse API/HTML payload into a normalized attack snapshot.
const source = $json;
const checkedAt = source.checkedAt || new Date().toISOString();

const rawBody = typeof source.body === 'string'
  ? source.body
  : (typeof source.data === 'string' ? source.data : JSON.stringify(source.data || source));

let parsedJson = null;
try {
  parsedJson = JSON.parse(rawBody);
} catch (_) {}

const toBool = (value) => {
  if (typeof value === 'boolean') return value;
  if (typeof value === 'number') return value > 0;
  const text = String(value || '').trim().toLowerCase();
  return ['1', 'true', 'yes', 'attack', 'hostile'].includes(text);
};

const pickString = (...values) => values.find(v => String(v || '').trim()) || '';

const detectFromJson = (obj) => {
  if (!obj || typeof obj !== 'object') return null;

  const hostileFleets = Number(
    obj.hostileFleets ?? obj.hostile_fleets ?? obj.hostiles ?? obj.attacks ?? 0
  ) || 0;

  const attackDetected =
    toBool(obj.attackDetected ?? obj.attack_detected ?? obj.underAttack ?? obj.hostile) ||
    hostileFleets > 0;

  return {
    attackDetected,
    hostileFleets,
    attacker: pickString(obj.attacker, obj.attackerName, obj.enemy, obj.player),
    target: pickString(obj.target, obj.planet, obj.moon),
    arrivalTime: pickString(obj.arrivalTime, obj.arrival, obj.eta),
    serverTime: pickString(obj.serverTime, obj.time),
    rawSummary: pickString(obj.rawSummary, obj.summary, obj.message)
  };
};

const detectFromText = (text) => {
  const normalized = String(text || '').replace(/\s+/g, ' ').trim();

  const attackDetected = /(under attack|incoming attack|hostile fleet|hostile fleets|attacco in arrivo|attacco)/i.test(normalized);
  const hostileMatch = normalized.match(/(\d+)\s+(hostile|incoming|enemy)\s+fleets?/i) || normalized.match(/hostile\s*[:=]\s*(\d+)/i);
  const arrivalMatch = normalized.match(/(?:arrival|eta|arrives?)\s*[:=]?\s*([0-2]?\d:[0-5]\d(?::[0-5]\d)?)/i);

  return {
    attackDetected,
    hostileFleets: hostileMatch ? Number(hostileMatch[1]) : 0,
    attacker: '',
    target: '',
    arrivalTime: arrivalMatch ? arrivalMatch[1] : '',
    serverTime: '',
    rawSummary: normalized ? normalized.slice(0, 280) : ''
  };
};

const normalized = detectFromJson(parsedJson) || detectFromJson(source) || detectFromText(rawBody);

const stateKey = [
  normalized.attackDetected ? '1' : '0',
  normalized.hostileFleets || 0,
  normalized.attacker || '',
  normalized.target || '',
  normalized.arrivalTime || '',
  normalized.rawSummary || ''
].join('|').toLowerCase();

return [{
  json: {
    ...normalized,
    checkedAt,
    stateKey,
    sendClearAlert: Boolean(source.sendClearAlert),
    statusUrl: source.statusUrl
  }
}];

// Compare with previous state to avoid duplicate alerts.
const staticData = this.getWorkflowStaticData('global');
const previous = staticData.lastAttackState || { attackDetected: false, stateKey: '' };
const current = $json;

const isNewAttack = Boolean(current.attackDetected) && !Boolean(previous.attackDetected);
const isMaterialUpdate = Boolean(current.attackDetected) && Boolean(previous.attackDetected) && current.stateKey !== previous.stateKey;
const isCleared = !Boolean(current.attackDetected) && Boolean(previous.attackDetected);

const shouldAlert = isNewAttack || isMaterialUpdate || (Boolean(current.sendClearAlert) && isCleared);

const title = isCleared
  ? '✅ OGame attack cleared'
  : (isNewAttack ? '🚨 OGame attack detected' : '⚠️ OGame attack update');

const lines = [
  title,
  'Checked at: ' + current.checkedAt,
  current.serverTime ? 'Server time: ' + current.serverTime : '',
  current.arrivalTime ? 'Arrival: ' + current.arrivalTime : '',
  current.attacker ? 'Attacker: ' + current.attacker : '',
  current.target ? 'Target: ' + current.target : '',
  Number.isFinite(current.hostileFleets) ? 'Hostile fleets: ' + current.hostileFleets : '',
  current.rawSummary ? 'Summary: ' + current.rawSummary : ''
].filter(Boolean);

// Persist latest state for next run dedup/comparison.
staticData.lastAttackState = {
  attackDetected: Boolean(current.attackDetected),
  stateKey: current.stateKey || '',
  hostileFleets: Number(current.hostileFleets) || 0,
  attacker: current.attacker || '',
  target: current.target || '',
  arrivalTime: current.arrivalTime || '',
  checkedAt: current.checkedAt || ''
};

return [{
  json: {
    ...current,
    shouldAlert,
    telegramText: lines.join('\n')
  }
}];
